create unique index if not exists payment_promises_group_schedule_unique_idx on public.payment_promises(promise_group_id,schedule_index) where promise_group_id is not null and btrim(promise_group_id)<>'';
create or replace function public.cpcm_create_payment_promises(target_account_id uuid, promise_group text, promises jsonb, actor_email text default null) returns jsonb language plpgsql security invoker set search_path=public as $$ declare a public.accounts%rowtype; item jsonb; inserted_count integer:=0; expected_count integer; idx integer; amt numeric; due date; begin select * into a from public.accounts where id=target_account_id for update; if not found then raise exception 'Account not found'; end if; if promise_group is null or btrim(promise_group)='' then raise exception 'Promise group required'; end if; if promises is null or jsonb_typeof(promises)<>'array' or jsonb_array_length(promises)=0 then raise exception 'Promise schedule required'; end if; expected_count:=jsonb_array_length(promises); for item in select * from jsonb_array_elements(promises) loop idx:=coalesce((item->>'schedule_index')::integer,0); amt:=coalesce((item->>'payment_amount')::numeric,0); due:=(item->>'due_date')::date; if idx<1 or amt<=0 or due is null then raise exception 'Invalid promise schedule item'; end if; insert into public.payment_promises(account_id,promise_group_id,schedule_index,schedule_total,debtor_name,account_number,payment_kind,payment_amount,total_amount,due_date,payment_method,method_last4,authorization_method,status,employee_email,assigned_to_email,notes,created_by_email,updated_at) values(target_account_id,promise_group,idx,expected_count,item->>'debtor_name',item->>'account_number',item->>'payment_kind',amt,coalesce((item->>'total_amount')::numeric,amt*expected_count),due,item->>'payment_method',nullif(item->>'method_last4',''),item->>'authorization_method',coalesce(nullif(item->>'status',''),'Pending Processing'),coalesce(item->>'employee_email',actor_email),item->>'assigned_to_email',item->>'notes',coalesce(actor_email,item->>'created_by_email','system'),now()) on conflict (promise_group_id,schedule_index) where promise_group_id is not null and btrim(promise_group_id)<>'' do nothing; if found then inserted_count:=inserted_count+1; end if; end loop; if inserted_count not in (0,expected_count) then raise exception 'Partial promise group detected'; end if; if inserted_count=expected_count then update public.accounts set status='Promise to Pay',disposition='Promise to Pay',updated_at=now() where id=target_account_id; end if; return jsonb_build_object('ok',true,'created_count',inserted_count,'already_exists',inserted_count=0,'promise_group_id',promise_group); end; $$;
